import { promises as fsp } from 'node:fs';
import { buildNestedPathIndex, extractBarePackHeader, extractPackedString } from '../../commands/bundle/manifest.js';
import { deduplicateAddons, readAddonPackageJson } from '../../commands/verify/addon-source.js';
export class InvalidBundleSourceError extends Error {
    bundlePath;
    constructor(bundlePath, cause) {
        const reason = cause instanceof Error ? cause.message : String(cause);
        super(`Bundle at ${bundlePath} could not be parsed as a bare-pack bundle.\n\n` +
            `  Reason: ${reason}\n\n` +
            '  Make sure the path points to a worker.bundle.js generated by bundleSdk.');
        this.name = 'InvalidBundleSourceError';
        this.bundlePath = bundlePath;
    }
}
export async function collectAddonsFromBundle(options) {
    const { bundlePath, projectRoot, diagnostics } = options;
    let bundleText;
    try {
        bundleText = await fsp.readFile(bundlePath, 'utf8');
    }
    catch (error) {
        throw new InvalidBundleSourceError(bundlePath, error);
    }
    let resolutions;
    try {
        const packed = extractPackedString(bundleText);
        const header = extractBarePackHeader(packed);
        resolutions = header.resolutions ?? {};
    }
    catch (error) {
        throw new InvalidBundleSourceError(bundlePath, error);
    }
    if (diagnostics !== undefined && Object.keys(resolutions).length === 0) {
        diagnostics.emptyResolutions = true;
    }
    const pathsByPackage = buildNestedPathIndex(resolutions, projectRoot);
    const addons = [];
    for (const [pkgName, candidates] of pathsByPackage) {
        for (const candidate of candidates) {
            const result = await readAddonPackageJson({
                packageJsonPath: candidate,
                expectedName: pkgName
            });
            if (result.isAddon && result.addon) {
                addons.push(result.addon);
            }
            else if (result.invalid !== undefined && diagnostics !== undefined) {
                diagnostics.invalidPackageJsons.push(result.invalid);
            }
        }
    }
    return deduplicateAddons(addons);
}
